		if (this.#minDurationTimer) clearTimeout(this.#minDurationTimer);
		this.#debounceTimer = this.#retryTimer = this.#minDurationTimer = undefined;
		this.#controller?.abort();
		this.#controller = undefined;
		++this.#requestId;
	}

	#resetAsyncState(): void {
		this.#cancelRequest();
		this.loading = false;
		this.loadError = undefined;
		this.searchTooShort = false;
		this.retryCount = 0;
	}

	#renderIfActive(): void {
		if (this.state === 'active') this.render();
	}
}

